    { id=20131, tab=2, tier=3, col=2, name="Primal Fury", icon="ability_racial_cannibalize", maxRank=2, prereqTalent=20128, prereqPoints=15, wired=true, tooltip={ "Gives you a 50% chance to gain an additional 5 Rage anytime you get a critical strike while in Bear and Dire Bear Form and your critical strikes from Cat Form abilities that add combo points have a 50% chance to add an additional combo point.", "Gives you a 100% chance to gain an additional 5 Rage anytime you get a critical strike while in Bear and Dire Bear Form and your critical strikes from Cat Form abilities that add combo points have a 100% chance to add an additional combo point." }, grant={ [1]=16958, [2]=16961 }, localized={deDE={name="Urfuror", tooltip={ "Gewährt Euch bei jedem kritischen Treffer in Bären- und Terrorbärengestalt eine Chance von 50%, zusätzlich 5 Wut zu erhalten. Kritische Treffer Eurer Fähigkeiten in Katzengestalt, die Combopunkte erzeugen, haben eine Chance von 50%, einen zusätzlichen Combopunkt zu erzeugen.", "Gewährt Euch bei jedem kritischen Treffer in Bären- und Terrorbärengestalt eine Chance von 100%, zusätzlich 5 Wut zu erhalten. Kritische Treffer Eurer Fähigkeiten in Katzengestalt, die Combopunkte erzeugen, haben eine Chance von 100%, einen zusätzlichen Combopunkt zu erzeugen." }}} },
