    { id=20149, tab=3, tier=2, col=2, name="Omen of Clarity", icon="spell_nature_crystalball", maxRank=1, prereqTalent=0, prereqPoints=10, wired=true, tooltip={ "Imbues the Druid with natural energy. Each of the Druid's melee attacks has a chance of causing the caster to enter a Clearcasting state. The Clearcasting state reduces the Mana, Rage or Energy cost of your next damage or healing spell or offensive ability by 100%. Lasts 30 min. (10 sec cooldown)" }, grant={ [1]=946269 }, localized={deDE={name="Omen der Klarsicht", tooltip={ "Erfüllt den Druiden mit natürlicher Energie. Jeder Nahkampfangriff des Druiden hat eine Chance, einen Freizauberzustand auszulösen. Dieser verringert die Mana-, Wut- oder Energiekosten Eures nächsten Schadens- oder Heilzaubers oder Eurer nächsten offensiven Fähigkeit um 100%. Hält 30 Min. lang an. (10 Sek. Abklingzeit)" }}} },
    { id=20150, tab=3, tier=3, col=1, name="Tranquil Spirit", icon="spell_holy_elunesgrace", maxRank=5, prereqTalent=0, prereqPoints=15, wired=true, tooltip={ "Reduces the mana cost of your Healing Touch and Tranquility spells by 2%.", "Reduces the mana cost of your Healing Touch and Tranquility spells by 4%.", "Reduces the mana cost of your Healing Touch and Tranquility spells by 6%.", "Reduces the mana cost of your Healing Touch and Tranquility spells by 8%.", "Reduces the mana cost of your Healing Touch and Tranquility spells by 10%." }, localized={deDE={name="Gelassener Geist", tooltip={ "Verringert die Manakosten Eurer Zauber 'Heilende Berührung' und 'Gelassenheit' um 2%.", "Verringert die Manakosten Eurer Zauber 'Heilende Berührung' und 'Gelassenheit' um 4%.", "Verringert die Manakosten Eurer Zauber 'Heilende Berührung' und 'Gelassenheit' um 6%.", "Verringert die Manakosten Eurer Zauber 'Heilende Berührung' und 'Gelassenheit' um 8%.", "Verringert die Manakosten Eurer Zauber 'Heilende Berührung' und 'Gelassenheit' um 10%." }}} },
    { id=20151, tab=3, tier=3, col=2, name="Improved Rejuvenation", icon="spell_nature_rejuvenation", maxRank=3, prereqTalent=0, prereqPoints=15, wired=true, tooltip={ "Increases the effect of your Rejuvenation spell by 5%.", "Increases the effect of your Rejuvenation spell by 10%.", "Increases the effect of your Rejuvenation spell by 15%." }, localized={deDE={name="Verbesserte Verjüngung", tooltip={ "Erhöht die Wirkung Eures Zaubers 'Verjüngung' um 5%.", "Erhöht die Wirkung Eures Zaubers 'Verjüngung' um 10%.", "Erhöht die Wirkung Eures Zaubers 'Verjüngung' um 15%." }}} },
    { id=20152, tab=3, tier=4, col=0, name="Nature's Swiftness", icon="spell_nature_ravenform", maxRank=1, prereqTalent=20147, prereqPoints=20, wired=true, tooltip={ "When activated, your next Nature spell becomes an instant cast spell." }, grant={ [1]=17116 }, localized={deDE={name="Schnelligkeit der Natur", tooltip={ "Nach der Aktivierung wird Euer nächster Naturzauber zu einem Spontanzauber." }}} },
    { id=20153, tab=3, tier=4, col=1, name="Gift of Nature", icon="spell_nature_protectionformnature", maxRank=5, prereqTalent=0, prereqPoints=20, wired=true, tooltip={ "Increases the effect of all healing spells by 2%.", "Increases the effect of all healing spells by 4%.", "Increases the effect of all healing spells by 6%.", "Increases the effect of all healing spells by 8%.", "Increases the effect of all healing spells by 10%." }, localized={deDE={name="Geschenk der Natur", tooltip={ "Erhöht die Wirkung aller Heilzauber um 2%.", "Erhöht die Wirkung aller Heilzauber um 4%.", "Erhöht die Wirkung aller Heilzauber um 6%.", "Erhöht die Wirkung aller Heilzauber um 8%.", "Erhöht die Wirkung aller Heilzauber um 10%." }}} },
    { id=20154, tab=3, tier=4, col=3, name="Improved Tranquility", icon="spell_nature_tranquility", maxRank=2, prereqTalent=0, prereqPoints=20, wired=true, tooltip={ "Reduces threat caused by Tranquility by 50%.", "Reduces threat caused by Tranquility by 100%." }, localized={deDE={name="Verbesserte Gelassenheit", tooltip={ "Verringert die durch 'Gelassenheit' verursachte Bedrohung um 50%.", "Verringert die durch 'Gelassenheit' verursachte Bedrohung um 100%." }}} },
    { id=20155, tab=3, tier=5, col=0, name="Empowered Touch", icon="ability_druid_empoweredtouch", maxRank=2, prereqTalent=0, prereqPoints=25, wired=true, tooltip={ "Your Healing Touch spell gains an additional 10% of your bonus healing effects.", "Your Healing Touch spell gains an additional 20% of your bonus healing effects." }, localized={deDE={name="Machtvolle Berührung", tooltip={ "Euer Zauber 'Heilende Berührung' erhält zusätzlich 10% Eurer Bonusheilung.", "Euer Zauber 'Heilende Berührung' erhält zusätzlich 20% Eurer Bonusheilung." }}} },
    { id=20156, tab=3, tier=5, col=2, name="Improved Regrowth", icon="spell_nature_resistnature", maxRank=5, prereqTalent=20151, prereqPoints=25, wired=true, tooltip={ "Increases the critical effect chance of your Regrowth spell by 10%.", "Increases the critical effect chance of your Regrowth spell by 20%.", "Increases the critical effect chance of your Regrowth spell by 30%.", "Increases the critical effect chance of your Regrowth spell by 40%.", "Increases the critical effect chance of your Regrowth spell by 50%." }, localized={deDE={name="Verbessertes Nachwachsen", tooltip={ "Erhöht die Chance auf einen kritischen Effekt Eures Zaubers 'Nachwachsen' um 10%.", "Erhöht die Chance auf einen kritischen Effekt Eures Zaubers 'Nachwachsen' um 20%.", "Erhöht die Chance auf einen kritischen Effekt Eures Zaubers 'Nachwachsen' um 30%.", "Erhöht die Chance auf einen kritischen Effekt Eures Zaubers 'Nachwachsen' um 40%.", "Erhöht die Chance auf einen kritischen Effekt Eures Zaubers 'Nachwachsen' um 50%." }}} },
    { id=20157, tab=3, tier=6, col=0, name="Living Spirit", icon="spell_nature_giftofthewaterspirit", maxRank=3, prereqTalent=0, prereqPoints=30, wired=true, tooltip={ "Increases your total Spirit by 5%.", "Increases your total Spirit by 10%.", "Increases your total Spirit by 15%." }, localized={deDE={name="Lebendiger Geist", tooltip={ "Erhöht Eure gesamte Willenskraft um 5%.", "Erhöht Eure gesamte Willenskraft um 10%.", "Erhöht Eure gesamte Willenskraft um 15%." }}} },
    { id=20158, tab=3, tier=6, col=1, name="Swiftmend", icon="inv_relics_idolofrejuvenation", maxRank=1, prereqTalent=20153, prereqPoints=30, wired=true, tooltip={ "Consumes a Rejuvenation or Regrowth effect on a friendly target to instantly heal them an amount equal to 12 sec. of Rejuvenation or 18 sec. of Regrowth." }, grant={ [1]=18562 }, localized={deDE={name="Rasche Heilung", tooltip={ "Verbraucht einen Effekt von 'Verjüngung' oder 'Nachwachsen' auf einem freundlichen Ziel und heilt es sofort um den Betrag, der 12 Sek. von 'Verjüngung' oder 18 Sek. von 'Nachwachsen' entspricht." }}} },
    { id=20159, tab=3, tier=6, col=2, name="Natural Perfection", icon="ability_druid_naturalperfection", maxRank=3, prereqTalent=0, prereqPoints=30, wired=true, tooltip={ "Your critical strike chance with all spells is increased by 1% and critical strikes against you give you the Natural Perfection effect reducing all damage taken by 2%. Stacks up to 3 times. Lasts 8 sec.", "Your critical strike chance with all spells is increased by 2% and critical strikes against you give you the Natural Perfection effect reducing all damage taken by 3%. Stacks up to 3 times. Lasts 8 sec.", "Your critical strike chance with all spells is increased by 3% and critical strikes against you give you the Natural Perfection effect reducing all damage taken by 4%. Stacks up to 3 times. Lasts 8 sec." }, grant={ [1]=33881, [2]=33882, [3]=33883 }, localized={deDE={name="Natürliche Perfektion", tooltip={ "Erhöht Eure kritische Trefferchance mit allen Zaubern um 1%. Kritische Treffer gegen Euch gewähren den Effekt 'Natürliche Perfektion', der jeglichen erlittenen Schaden um 2% verringert. Bis zu 3-mal stapelbar. Hält 8 Sek. lang an.", "Erhöht Eure kritische Trefferchance mit allen Zaubern um 2%. Kritische Treffer gegen Euch gewähren den Effekt 'Natürliche Perfektion', der jeglichen erlittenen Schaden um 3% verringert. Bis zu 3-mal stapelbar. Hält 8 Sek. lang an.", "Erhöht Eure kritische Trefferchance mit allen Zaubern um 3%. Kritische Treffer gegen Euch gewähren den Effekt 'Natürliche Perfektion', der jeglichen erlittenen Schaden um 4% verringert. Bis zu 3-mal stapelbar. Hält 8 Sek. lang an." }}} },
    { id=20160, tab=3, tier=7, col=1, name="Empowered Rejuvenation", icon="ability_druid_empoweredrejuvination", maxRank=5, prereqTalent=0, prereqPoints=35, wired=true, tooltip={ "The bonus healing effects of your healing over time spells is increased by 4%.", "The bonus healing effects of your healing over time spells is increased by 8%.", "The bonus healing effects of your healing over time spells is increased by 12%.", "The bonus healing effects of your healing over time spells is increased by 16%.", "The bonus healing effects of your healing over time spells is increased by 20%." }, localized={deDE={name="Machtvolle Verjüngung", tooltip={ "Erhöht den Bonusheilungsanteil Eurer regelmäßigen Heilzauber um 4%.", "Erhöht den Bonusheilungsanteil Eurer regelmäßigen Heilzauber um 8%.", "Erhöht den Bonusheilungsanteil Eurer regelmäßigen Heilzauber um 12%.", "Erhöht den Bonusheilungsanteil Eurer regelmäßigen Heilzauber um 16%.", "Erhöht den Bonusheilungsanteil Eurer regelmäßigen Heilzauber um 20%." }}} },
    { id=20161, tab=3, tier=8, col=1, name="Tree of Life", icon="ability_druid_treeoflife", maxRank=1, prereqTalent=20160, prereqPoints=40, wired=true, tooltip={ "Shapeshift into the Tree of Life. While in this form you increase healing received by 25% of your total Spirit for all party members within 45 yards, and you can only cast Restoration spells in addition to Innervate, Barkskin, Nature's Grasp and Thorns. The act of shapeshifting frees the caster of Polymorph and Movement Impairing effects." }, grant={ [1]=946276 }, localized={deDE={name="Baum des Lebens", tooltip={ "Verwandelt Euch in den Baum des Lebens. In dieser Gestalt erhöht Ihr die erhaltene Heilung aller Gruppenmitglieder im Umkreis von 45 Metern um 25% Eurer gesamten Willenskraft. Ihr könnt nur Wiederherstellungszauber sowie 'Anregen', 'Baumrinde', 'Griff der Natur' und 'Dornen' wirken. Die Verwandlung befreit den Zaubernden von Verwandlungs- und bewegungseinschränkenden Effekten." }}} },
